    internal InnerDataAutomationProjectSensitiveDataConfigurationFactory SensitiveDataConfigurationFactory { get; set; }

    internal InnerDataAutomationProjectAudioLanguageConfigurationFactory LanguageConfigurationFactory { get; set; }

    internal InnerDataAutomationProjectModalityProcessingConfigurationFactory ModalityProcessingFactory { get; set; }

    protected override Humidifier.Bedrock.DataAutomationProjectTypes.AudioOverrideConfiguration Create()
    {
        var audioOverrideConfigurationResult = CreateAudioOverrideConfiguration();
        factoryAction?.Invoke(audioOverrideConfigurationResult);

        return audioOverrideConfigurationResult;
    }

    private Humidifier.Bedrock.DataAutomationProjectTypes.AudioOverrideConfiguration CreateAudioOverrideConfiguration()
    {
        var audioOverrideConfigurationResult = new Humidifier.Bedrock.DataAutomationProjectTypes.AudioOverrideConfiguration();

        return audioOverrideConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Bedrock.DataAutomationProjectTypes.AudioOverrideConfiguration result)
    {
        base.CreateChildren(result);

        result.SensitiveDataConfiguration ??= SensitiveDataConfigurationFactory?.Build();
        result.LanguageConfiguration ??= LanguageConfigurationFactory?.Build();
        result.ModalityProcessing ??= ModalityProcessingFactory?.Build();
    }

} // End Of Class

